example.good:
#!/usr/bin/env bash
set -euo pipefail  # Explicit error handling
shopt -s nullglob  # Explicit glob behavior

examples.bad:
VERSION=1.0.0  # Not readonly, can be accidentally modified
CONFIG_DIR=~/.config/myapp  # Tilde may not expand in all contexts

my_function() {
    input=$1  # Global variable pollution
}

examples.good:
#!/usr/bin/env bash
set -euo pipefail

cleanup() {
    rm -f "$TEMP_FILE"
}
trap cleanup EXIT

TEMP_FILE=$(mktemp)
# Work with temp file...

examples.bad:
inst() {
    pkg=$1
    # What does this do?
}
